sys_script_include.script:
var RegisterAttendeeHelper = Class.create();
RegisterAttendeeHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

registerAttendee: function() {
        var firstName = this.getParameter('sysparm_first_name');
        var lastName = this.getParameter('sysparm_last_name');
        var email = this.getParameter('sysparm_email');
        var contactNumber = this.getParameter('sysparm_contact_number');
        var eventId = this.getParameter('sysparm_event_id');

        var gr = new GlideRecord('x_1790229_event_ma_attendee'); // Use your correct table name
        gr.initialize();
        gr.setValue('u_first_name', firstName);
        gr.setValue('u_last_name', lastName);
        gr.setValue('u_email', email);
        gr.setValue('u_contact_number', contactNumber);
        gr.setValue('u_event_id', eventId);

        var attendeeSysId = gr.insert();
        return attendeeSysId ? 'Attendee registered successfully.' : 'Failed to register attendee.';
    },
    type: 'RegisterAttendeeHelper'
});
